import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 처리 가능한 유형: API 오류 표 기준 승인·반려만 허용한다 (보류는 422)
const ALLOWED_ACTIONS = ['승인', '반려'];

@Controller('api/v1')
export class FnSfr04007Controller {
  @Post('/approval-lines/:approvalLineId/process')
  @HttpCode(200)
  async processApprovalLine(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['approvalLineId'];
    if (typeof idText !== 'string' || !/^[0-9]+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재선 ID가 올바르지 않습니다.');
    }
    const actionType = data['actionType'];
    if (typeof actionType !== 'string' || actionType.trim() === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '처리 유형을 입력해 주세요.');
    }
    const rawOpinion = data['opinion'];
    if (rawOpinion !== undefined && rawOpinion !== null && typeof rawOpinion !== 'string') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재 의견 형식이 올바르지 않습니다.');
    }
    const opinion = typeof rawOpinion === 'string' && rawOpinion.trim() !== '' ? rawOpinion.trim() : null;
    if (!ALLOWED_ACTIONS.includes(actionType)) {
      throw new ApiError(422, 'APPROVAL_ACTION_INVALID', '처리 구분은 승인 또는 반려만 선택할 수 있습니다.');
    }
    if (actionType === '반려' && opinion === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '반려할 때는 결재 의견을 입력해 주세요.');
    }
    return transaction(async (db) => {
      const lines = await db.query(
        `SELECT l.approval_document_id AS "documentId",
                l.approver_id AS "approverId",
                l.line_group AS "lineGroup",
                l.sequence_no AS "sequenceNo",
                l.action_type AS "actionType",
                d.approval_status AS "documentStatus"
           FROM approval_line l
           JOIN approval_document d ON d.approval_document_id = l.approval_document_id
          WHERE l.approval_line_id = CAST(:lineId AS bigint)
          FOR UPDATE OF l`,
        { lineId: idText },
      );
      if (lines.length === 0) {
        throw new ApiError(404, 'APPROVAL_LINE_NOT_FOUND', '결재선을 찾을 수 없습니다.');
      }
      const line = lines[0];
      const notMyTurn = new ApiError(409, 'APPROVAL_NOT_MY_TURN', '결재 차례가 아니거나 이미 처리된 문서입니다.');
      if (String(line.approverId) !== String(user.id)) {
        throw notMyTurn;
      }
      if (line.actionType !== null && line.actionType !== undefined) {
        throw notMyTurn;
      }
      // 가정: 문서가 결재대기·진행중일 때만 처리할 수 있다
      if (line.documentStatus !== '결재대기' && line.documentStatus !== '진행중') {
        throw notMyTurn;
      }
      // 가정: 같은 결재선 구분 안에서 앞 순서가 모두 승인되어야 내 차례이다
      const before = await db.query(
        `SELECT COUNT(*) AS "cnt"
           FROM approval_line
          WHERE approval_document_id = CAST(:documentId AS bigint)
            AND line_group = CAST(:lineGroup AS integer)
            AND sequence_no < CAST(:sequenceNo AS integer)
            AND (action_type IS NULL OR action_type <> '승인')`,
        { documentId: line.documentId, lineGroup: line.lineGroup, sequenceNo: line.sequenceNo },
      );
      if (Number(before[0].cnt) > 0) {
        throw notMyTurn;
      }
      const updated = await db.query(
        `UPDATE approval_line
            SET action_type = :actionType,
                opinion = :opinion,
                approver_id = CAST(:userId AS bigint),
                processed_at = now(),
                updated_at = now()
          WHERE approval_line_id = CAST(:lineId AS bigint)
        RETURNING approval_line_id AS "approvalLineId",
                  action_type AS "actionType",
                  processed_at AS "processedAt"`,
        { actionType, opinion, userId: user.id, lineId: idText },
      );
      if (actionType === '반려') {
        // 반려 시 문서는 반려 상태가 된다
        await db.execute(
          `UPDATE approval_document
              SET approval_status = '반려', updated_at = now()
            WHERE approval_document_id = CAST(:documentId AS bigint)`,
          { documentId: line.documentId },
        );
      } else {
        const rest = await db.query(
          `SELECT COUNT(*) AS "cnt"
             FROM approval_line
            WHERE approval_document_id = CAST(:documentId AS bigint)
              AND action_type IS NULL`,
          { documentId: line.documentId },
        );
        // 가정: 모든 결재자가 승인하면 문서는 승인, 남아 있으면 진행중
        const nextStatus = Number(rest[0].cnt) === 0 ? '승인' : '진행중';
        await db.execute(
          `UPDATE approval_document
              SET approval_status = :status, updated_at = now()
            WHERE approval_document_id = CAST(:documentId AS bigint)`,
          { status: nextStatus, documentId: line.documentId },
        );
      }
      return updated[0];
    });
  }
}

