import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, NumberInput, Select, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr04007Page({ role, notify }: PageProps) {
  const [results, setResults] = useState<Row[]>([]);
  const [open, setOpen] = useState(false);
  const [lineId, setLineId] = useState<number | string>('');
  const [actionType, setActionType] = useState('');
  const [opinion, setOpinion] = useState('');

  const approved = results.filter((r) => r.actionType === '승인').length;
  const rejected = results.filter((r) => r.actionType === '반려').length;

  function openDrawer() {
    setLineId('');
    setActionType('');
    setOpinion('');
    setOpen(true);
  }

  async function submit() {
    if (lineId === '' || typeof lineId !== 'number') {
      throw new Error('결재선 ID를 숫자로 입력해 주세요.');
    }
    if (actionType === '') {
      throw new Error('처리 유형을 선택해 주세요.');
    }
    if (actionType === '반려' && opinion.trim() === '') {
      throw new Error('반려할 때는 결재 의견을 입력해 주세요.');
    }
    const res = await call('POST', `/approval-lines/${lineId}/process`, role, {
      actionType,
      opinion: opinion.trim() === '' ? undefined : opinion.trim(),
    });
    setResults([res, ...results]);
    setOpen(false);
    notify(actionType === '승인' ? '승인했습니다.' : '반려했습니다.');
  }

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles
          items={[
            ['처리 건수', results.length],
            ['승인', approved],
            ['반려', rejected],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>처리 결과</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>결재 처리</button>
        </Band>
        <DataTable
          columns={[
            { key: 'approvalLineId', label: '결재선 ID' },
            { key: 'actionType', label: '처리 유형', render: (r) => <Badge value={r.actionType} /> },
            { key: 'processedAt', label: '처리 일시', render: (r) => <DateText value={r.processedAt} time /> },
          ]}
          rows={results}
          empty="이 화면에서 처리한 결재문서가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="결재문서 승인·반려" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="처리">
            <Field label="결재선 ID" required>
              <NumberInput value={lineId} onChange={setLineId} />
            </Field>
            <Field label="처리 유형" required>
              <Select
                value={actionType}
                onChange={setActionType}
                options={[['승인', '승인'], ['반려', '반려']]}
              />
            </Field>
            <Field label="결재 의견" required={actionType === '반려'} wide hint="반려할 때는 필수입니다.">
              <TextInput value={opinion} onChange={setOpinion} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
